const examResultRows = `-- name: ExamResultRows :many
select u.id as student_id, u.full_name, coalesce(u.student_code, '') as student_code,
       a.id as attempt_id, a.status as attempt_status, a.auto_score, a.adjusted_score, a.submitted_at, a.submit_reason,
       coalesce(case when $1::boolean then (select count(*) from similarity_reports r where r.course_id = e.course_id and r.exam_id = e.id and r.flagged
              and (r.attempt_a = a.id or r.attempt_b = a.id)
              and r.run_id = (select l.run_id from similarity_reports l where l.course_id = e.course_id and l.exam_id = e.id order by l.created_at desc, l.id desc limit 1)) end, 0)::int as sim_flags,
       coalesce(case when $1::boolean then (select count(*) from exam_events ev where ev.course_id = e.course_id and ev.attempt_id = a.id and ev.type = 'TAB_HIDDEN') end, 0)::int as tab_hidden,
       coalesce(case when $1::boolean then (select count(*) from exam_events ev where ev.course_id = e.course_id and ev.attempt_id = a.id and ev.type = 'PASTE') end, 0)::int as paste
from exams e
join enrollments en on en.course_id = e.course_id and en.role_in_course = 'STUDENT' and en.status = 'ACTIVE'
join users u on u.id = en.user_id
left join exam_attempts a on a.course_id = e.course_id and a.exam_id = e.id and a.student_id = u.id
where e.course_id = $2 and e.id = $3
  and ($4::text = '' or ($4::text = 'ABSENT' and a.id is null) or ($4::text <> 'ABSENT' and a.status::text = $4::text))
order by u.id
`

type ExamResultRowsParams struct {
	WithFlags bool
	CourseID  uuid.UUID
	ExamID    uuid.UUID
	Status    string
}

type ExamResultRowsRow struct {
	StudentID     uuid.UUID
	FullName      string
	StudentCode   string
	AttemptID     *uuid.UUID
	AttemptStatus *AttemptStatus
	AutoScore     decimal.NullDecimal
	AdjustedScore decimal.NullDecimal
	SubmittedAt   *time.Time
	SubmitReason  *AttemptSubmitReason
	SimFlags      int32
	TabHidden     int32
	Paste         int32
}

// Mọi sinh viên ACTIVE của lớp + lượt của họ (nếu có). Ô tìm theo tên / MSSV lọc ở service (MSSV không được dùng làm điều kiện truy vấn — SRS 4.2.5). Sắp xếp và phân trang con trỏ làm ở service (lớp ≤ 1.000 sinh viên: một truy vấn, số truy vấn không đổi theo cỡ lớp).
func (q *Queries) ExamResultRows(ctx context.Context, arg ExamResultRowsParams) ([]ExamResultRowsRow, error) {
	rows, err := q.db.Query(ctx, examResultRows,
		arg.WithFlags,
		arg.CourseID,
		arg.ExamID,
		arg.Status,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ExamResultRowsRow{}
	for rows.Next() {
		var i ExamResultRowsRow
		if err := rows.Scan(
			&i.StudentID,
			&i.FullName,
			&i.StudentCode,
			&i.AttemptID,
			&i.AttemptStatus,
			&i.AutoScore,
			&i.AdjustedScore,
			&i.SubmittedAt,
			&i.SubmitReason,
			&i.SimFlags,
			&i.TabHidden,
			&i.Paste,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

